def solve_variant(g, mode):
    # mode 'frame_then_fill': frame(2) first, then flood outside over {0}, walls 1&2, enclosed->3
    # mode 'fill_then_frame': fill enclosed over {0} walls 1, frame 2 on perimeter of union bbox
    H,W=len(g),len(g[0]); a=[r[:] for r in g]
    if mode=='frame_then_fill':
        for c_ in cc(g):
            rs=[p for p,_ in c_]; cs=[q for _,q in c_]
            R0,R1,C0,C1=min(rs)-1,max(rs)+1,min(cs)-1,max(cs)+1
            R0=max(R0,0);C0=max(C0,0);R1=min(R1,H-1);C1=min(C1,W-1)
            for i in range(R0,R1+1):
                for j in range(C0,C1+1):
                    if g[i][j]==0 and (i==R0 or i==R1 or j==C0 or j==C1): a[i][j]=2
        vis=[[False]*W for _ in range(H)]
        seed=[(0,-1),(0,W-1),(-1,0),(H-1,0)]
        for x,y in seed:
            if 0<=x<H and 0<=y<W: vis[x][y]=True
        st=[(0,-1)]
        while st:
            x,y=st.pop()
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and not vis[nx][ny] and a[nx][ny]==0:
                        vis[nx][ny]=True; st.append((nx,ny))
        for i in range(H):
            for j in range(W):
                if a[i][j]==0 and not vis[i][j]: a[i][j]=3
    elif mode=='fill_then_frame':
        pts=[(p,q) for p in range(H) for q in range(W) if g[p][q]==1]
        r0,r1,c0,c1=min(p for p,_ in pts),max(p for p,_ in pts),min(q for _,q in pts),max(q for _,q in pts)
        # enclose zeros by flood from border blocked by 1s
        vis=[[False]*W for _ in range(H)]
        seed=[(0,-1),(0,W-1),(-1,0),(H-1,0)]
        for x,y in seed:
            if 0<=x<H and 0<=y<W: vis[x][y]=True
        st=[(0,-1)]
        while st:
            x,y=st.pop()
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and not vis[nx][ny] and a[nx][ny]==0:
                        vis[nx][ny]=True; st.append((nx,ny))
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                if a[i][j]==0 and not vis[i][j]: a[i][j]=3
        for c_ in cc(g):
            rs=[p for p,_ in c_]; cs=[q for _,q in c_]
            R0,R1,C0,C1=min(rs)-1,max(rs)+1,min(cs)-1,max(cs)+1
            R0=max(R0,0);C0=max(C0,0);R1=min(R1,H-1);C1=min(C1,W-1)
            for i in range(R0,R1+1):
                for j in range(C0,C1+1):
                    if g[i][j]==0 and (i==R0 or i==R1 or j==C0 or j==C1): a[i][j]=2
    return a

