def solve(a):
    H,W=len(a),len(a[0])
    from collections import Counter
    cnt=Counter(v for r in a for v in r); bg=cnt.most_common(1)[0][0]
    seen=set();comps=[]
    for y in range(H):
        for x in range(W):
            if a[y][x]!=bg and (y,x) not in seen:
                st=[(y,x)];comp=[];seen.add((y,x))
                while st:
                    cy,cx=st.pop();comp.append((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        p=(cy+dy,cx+dx)
                        if 0<=p[0]<H and 0<=p[1]<W and a[p[0]][p[1]]!=bg and p not in seen:
                            seen.add(p);st.append(p)
                comps.append(comp)
    kept=[c for c in comps if len(c)>1 or any(a[ry][cx]==a[y][x] for ry,cx in c if False) or True]
    out=[r[:] for r in a]
    changed=True
    while changed:
        changed=False
        for comp in comps:
            sset=set(comp);size=len(sset)
            xs=[c for _,c in sset]; ys=[r for r,_ in sset]
            x0,x1,y0,y1=min(xs),max(xs),min(ys),max(ys)
            colm=Counter(a[r][c] for r,c in sset).most_common(1)[0][0]
            # recolor non-comp cells inside bbox that touch comp by majority neighbor color among {colm} U neighbors... use refined rule:
            # candidates = colors of touching same-colored neighbors OR comp's own color
            cand={}
            for r in range(y0,y1+1):
                for c in range(x0,x1+1):
                    if (r,c) in sset: continue
                    nbcol={}
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        p=(r+dr,c+dc)
                        if 0<=p[0]<H and 0<=p[1]<W and a[p[0]][p[1]]!=bg:
                            nbcol[a[p[0]][p[1]]]=nbcol.get(a[p[0]][p[1]],0)+1
                    cand[(r,c)]=nbcol
            new_changed=False
            for (r,c),nbcol in cand.items():
                if nbcol and a[r][c]==bg:
                    best=max(nbcol.items(), key=lambda kv:(kv[1],-abs(kv[0]-colm)))
                    out[r][c]=best[0]
                    new_changed=True
            changed|=new_changed
    return out
