                        if 0<=a<H and 0<=b<W and A[a][b]==1 and not seen[a][b]:
                            seen[a][b]=True; st.append((a,b))
                comps.append(cells)
    def vis_same(pts,row=None,col=None):
        # fill zeros between two 1s of the given component set along a row or col
        res=[]
        for y in range(H):
            xs=sorted(x for x in pts if (y,x) in pts)
            for p,q in zip(xs,xs[1:]):
                for z in range(p+1,q): res.append((y,z)); 
        for x in range(W):
            ys=sorted(y for y in pts if (y,x) in pts)
            for p,q in zip(ys,ys[1:]):
                for z in range(p+1,q): res.append((z,x))
        return set(res)
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        pts={(y,x) for y,x in comp}
        g=vis_same(pts)
        for y,x in g:
            if r0<=y<=r1 and c0<=x<=c1: out[y][x]=1
    return out
